// Filter companies with OAuth connected
// This node runs once for all items and returns an array
const companies = $input.all();
const companiesWithOAuth = companies
  .map(item => item.json)
  .filter(company => company.has_oauth_connected);

console.log(`Found ${companiesWithOAuth.length} companies with OAuth connected`);

if (companiesWithOAuth.length === 0) {
  console.log('No companies with OAuth connected. Workflow will exit.');
  return [];
}

// Return array of companies with all needed fields
// n8n will automatically create one item per array element
return companiesWithOAuth.map(company => ({
  company_id: company.company_id,
  company_name: company.name,
  company_email: company.email,
  n8n_credential_id: company.n8n_credential_id || null
}));

// Prepare URL for getting Gmail token
// This node runs once for each company item automatically
// n8n processes items one by one when previous node outputs multiple items
// In 'runOnceForEachItem' mode, use $json to access current item (NOT $input.all())

console.log('=== Prepare Token Request - Debug ===');
console.log('$json:', JSON.stringify($json, null, 2));

// Access data from current item (n8n processes items one by one)
// In runOnceForEachItem mode, $json contains the current item
const companyData = $json;

if (!companyData) {
  console.error('ERROR: No company data found!');
  console.error('$json:', $json);
  throw new Error('No company data received from previous node');
}

console.log('Company data found:', JSON.stringify(companyData, null, 2));

const companyId = companyData.company_id;
const credentialId = companyData.n8n_credential_id;

if (!companyId) {
  console.error('ERROR: company_id is missing!');
  console.error('Full companyData:', JSON.stringify(companyData, null, 2));
  throw new Error('company_id is missing from input data');
}

if (!credentialId) {
  console.warn(`Company ${companyId} has no n8n_credential_id. Skipping.`);
  return null;
}

// Use host.docker.internal for Docker container to access host
// Works on Docker Desktop (Windows/Mac), for Linux might need 172.17.0.1
const url = `http://host.docker.internal:8000/api/companies/${companyId}/gmail-token`;

console.log(`Getting Gmail token for company: ${companyId} (${companyData.company_name})`);
console.log(`Credential ID: ${credentialId}`);
console.log(`URL: ${url}`);

return {
  company_id: companyId,
  company_name: companyData.company_name,
  company_email: companyData.company_email,
  n8n_credential_id: credentialId,
  token_url: url
};

// Merge token data with company data for Gmail API call
// The backend returns: {company_id, company_email, access_token, expires_at}
// We need to get company_name and n8n_credential_id from Prepare Token Request

const tokenData = $json;

console.log('Merge Token Data - Token response:', JSON.stringify(tokenData, null, 2));

if (!tokenData || !tokenData.access_token) {
  console.error('ERROR: Token data missing or invalid');
  console.error('Token data:', JSON.stringify(tokenData, null, 2));
  throw new Error('access_token is missing from token response');
}

// The backend response includes company_id and company_email
// We need to get company_name and n8n_credential_id from Prepare Token Request node
// In runOnceForEachItem mode, use $('NodeName').item.json to get corresponding item
const previousData = $('Prepare Token Request').item.json;

console.log('Merge Token Data - Previous node data:', JSON.stringify(previousData, null, 2));

// Merge: use token response for token data, previous node for company metadata
const merged = {
  company_id: tokenData.company_id || previousData?.company_id,
  company_name: previousData?.company_name || 'Unknown',
  company_email: tokenData.company_email || previousData?.company_email,
  n8n_credential_id: previousData?.n8n_credential_id || null,
  access_token: tokenData.access_token,
  expires_at: tokenData.expires_at
};

if (!merged.company_id) {
  console.error('ERROR: Company ID missing after merge');
  console.error('Merged data:', JSON.stringify(merged, null, 2));
  throw new Error('Company ID is missing - cannot proceed');
}

console.log('Merge Token Data - Successfully merged:', JSON.stringify({
  company_id: merged.company_id,
  company_name: merged.company_name,
  has_access_token: !!merged.access_token,
  has_credential_id: !!merged.n8n_credential_id
}, null, 2));

return merged;

// Check if there are new emails and pass through data if messages exist
// This replaces the IF node to ensure proper evaluation
const gmailResponse = $json;

console.log('=== Has New Emails Check ===');
console.log('Gmail response:', JSON.stringify(gmailResponse, null, 2));
console.log('Has messages property:', 'messages' in gmailResponse);
console.log('Messages value:', gmailResponse.messages);
console.log('Is array:', Array.isArray(gmailResponse.messages));
console.log('Messages length:', gmailResponse.messages ? gmailResponse.messages.length : 0);

// Check if messages exist and is a non-empty array
const hasMessages = gmailResponse.messages && 
                    Array.isArray(gmailResponse.messages) && 
                    gmailResponse.messages.length > 0;

console.log('Has messages (boolean):', hasMessages);

if (!hasMessages) {
  console.log('No messages found - returning null to stop workflow');
  return null; // Return null to stop processing this branch
}

console.log(`Found ${gmailResponse.messages.length} messages - passing through data`);
// Return the data to continue processing
return gmailResponse;

// Process each message ID and prepare for fetching full message details
// This node processes all items at once to access data from previous nodes
// Receives data from 'Has New Emails?' node (which passes through data from 'Check Gmail Inbox via API')

console.log('=== Prepare Message IDs - Debug START ===');

// Get all input items from Has New Emails? node (true branch)
// This data comes from Check Gmail Inbox via API
const allItems = $input.all();
console.log(`Received ${allItems.length} items from Has New Emails? (true branch)`);

if (allItems.length === 0) {
  console.warn('WARNING: No items received from Check Gmail Inbox via API');
  return [];
}

// Log first item structure for debugging
if (allItems.length > 0) {
  console.log('First item structure:', JSON.stringify(allItems[0].json, null, 2));
}

// Get all items from Merge Token Data node
let allMergedData = [];
try {
  allMergedData = $('Merge Token Data').all();
  console.log(`Found ${allMergedData.length} items from Merge Token Data`);
} catch (e) {
  console.error('ERROR accessing Merge Token Data:', e.message);
  throw new Error('Cannot access Merge Token Data node: ' + e.message);
}

if (allMergedData.length === 0) {
  console.error('ERROR: No data from Merge Token Data node');
  throw new Error('Merge Token Data node returned no items');
}

if (allMergedData.length !== allItems.length) {
  console.warn(`Item count mismatch: ${allItems.length} Gmail responses vs ${allMergedData.length} companies`);
  console.warn('Will match by index (item 0 with item 0, etc.)');
}

const allProcessedMessages = [];

// Process each item from Gmail API
for (let i = 0; i < allItems.length; i++) {
  const messagesResponse = allItems[i].json;
  const mergedData = allMergedData[i]?.json || allMergedData[0]?.json; // Fallback to first if count mismatch

  console.log(`\n--- Processing item ${i} ---`);
  console.log('Gmail response keys:', Object.keys(messagesResponse || {}));
  console.log('Has messages property:', 'messages' in (messagesResponse || {}));
  console.log('Messages value:', messagesResponse.messages);
  console.log('Messages type:', typeof messagesResponse.messages);
  console.log('Is array:', Array.isArray(messagesResponse.messages));
  console.log('Messages count:', messagesResponse.messages?.length || 0);
  console.log('Company name:', mergedData?.company_name);

  if (!mergedData) {
    console.error(`ERROR: No company data found for item ${i}`);
    continue;
  }

  // Extract messages array from response
  const messageIds = messagesResponse.messages || [];

  if (!Array.isArray(messageIds)) {
    console.error(`ERROR: messages is not an array in item ${i}:`, typeof messageIds);
    console.error('Full response:', JSON.stringify(messagesResponse, null, 2));
    continue;
  }

  if (messageIds.length === 0) {
    console.log(`No messages found in item ${i} for ${mergedData.company_name} - skipping`);
    continue;
  }

  console.log(`Found ${messageIds.length} messages for ${mergedData.company_name}`);

  // Prepare data for each message ID
  for (const msg of messageIds) {
    const messageId = msg.id;

    if (!messageId) {
      console.warn('Message missing ID:', msg);
      continue;
    }

    allProcessedMessages.push({
      company_id: mergedData.company_id,
      company_email: mergedData.company_email,
      company_name: mergedData.company_name,
      n8n_credential_id: mergedData.n8n_credential_id,
      access_token: mergedData.access_token,
      message_id: messageId
    });
  }

  console.log(`✓ Processed ${messageIds.length} messages for ${mergedData.company_name}`);
}

console.log(`\n=== Prepare Message IDs - Debug END ===`);
console.log(`Total: Found ${allProcessedMessages.length} messages to process across all companies`);

if (allProcessedMessages.length === 0) {
  console.log('No messages to process - returning empty array (this is OK if no unread emails)');
  return [];
}

// Return array - n8n will automatically create one item per array element
return allProcessedMessages;

// Extract email data from Gmail message
// This node runs once for each message from Get Full Message Details
const message = $json;

// Get company data from Prepare Message IDs node by matching message_id
// The input to Get Full Message Details was from Prepare Message IDs
let companyData = null;
try {
  const prepareMessageIdsNode = $('Prepare Message IDs');
  if (prepareMessageIdsNode && prepareMessageIdsNode.all) {
    // Get all items from Prepare Message IDs
    const allItems = prepareMessageIdsNode.all();
    const currentMessageId = message.id;

    // Find the item with matching message_id
    const matchingItem = allItems.find(item => item.json.message_id === currentMessageId);
    if (matchingItem) {
      companyData = matchingItem.json;
    } else {
      console.warn(`Could not find company data for message_id: ${currentMessageId}`);
      console.warn('Available message_ids:', allItems.map(item => item.json.message_id).slice(0, 5));
    }
  }
} catch (e) {
  console.error('Error accessing Prepare Message IDs:', e.message);
}

if (!companyData) {
  console.error('ERROR: Could not get company data');
  console.error('Message ID:', message.id);
  throw new Error('Company data not found - cannot extract email data');
}

console.log('Extract Email Data - Message ID:', message.id);
console.log('Extract Email Data - Company:', companyData.company_name);

// Extract headers
const headers = message.payload.headers || [];
const getHeader = (name) => {
  const header = headers.find(h => h.name.toLowerCase() === name.toLowerCase());
  return header ? header.value : '';
};

// Get from and to addresses
const fromAddress = getHeader('From') || '';
const toAddress = getHeader('To') || companyData.company_email;

// FILTER: Skip sent emails - if "from" contains company email, it's a sent email
// Extract email from "From" field (handles formats like "Name <email@domain.com>" or just "email@domain.com")
const extractEmailFromField = (field) => {
  if (!field) return '';
  // Match email pattern in the field
  const emailMatch = field.match(/[\w\.-]+@[\w\.-]+\.\w+/);
  return emailMatch ? emailMatch[0].toLowerCase() : field.toLowerCase();
};

const fromEmail = extractEmailFromField(fromAddress);
const companyEmailLower = companyData.company_email.toLowerCase();

if (fromEmail === companyEmailLower) {
  console.log(`Skipping sent email - From: ${fromAddress}, Company: ${companyData.company_email}`);
  console.log(`Message ID: ${message.id} - This is a sent email, not an inbox email`);
  return null; // Return null to skip this email (n8n will filter it out)
}

console.log(`Processing inbox email - From: ${fromAddress}, To: ${toAddress}`);

// Extract body
let body = '';
if (message.payload.body && message.payload.body.data) {
  body = Buffer.from(message.payload.body.data, 'base64').toString('utf-8');
} else if (message.payload.parts) {
  for (const part of message.payload.parts) {
    if (part.mimeType === 'text/plain' && part.body && part.body.data) {
      body = Buffer.from(part.body.data, 'base64').toString('utf-8');
      break;
    } else if (part.mimeType === 'text/html' && part.body && part.body.data) {
      // Fallback to HTML if plain text not available
      body = Buffer.from(part.body.data, 'base64').toString('utf-8');
    }
  }
}

return {
  credential_id: companyData.n8n_credential_id,
  company_id: companyData.company_id,
  email_data: {
    subject: getHeader('Subject') || '(No Subject)',
    body: body || '',
    from: fromAddress,
    to: toAddress,
    thread_id: message.threadId || null,
    gmail_message_id: message.id || null
  }
};
